SELECT SQL_CALC_FOUND_ROWS ppi.payment_sub_info_id, ppi.mb_id, ppi.customer_uid, ppi.payment_period_cd_id, ppsc.code_type, ppsc.code_value, ppsc.code_nm, ppi.payment_start_day, ppi.payment_last_day, gsi.it_id, gsi.it_name, COALESCE(( SELECT SUM( CASE WHEN ppsci.io_type = 0 THEN ((ppsci.ct_price) * ppsci.ct_qty) WHEN ppsci.io_type = 1 THEN (sio.io_price * ppsci.ct_qty) ELSE 0 END ) FROM pet_payment_sub_cart_info ppsci JOIN g5_shop_item_option sio ON ppsci.io_id = sio.io_id AND ppsci.it_id = sio.it_id WHERE ppsci.payment_sub_info_id = ppi.payment_sub_info_id AND ppsci.del_fl = 0 ), 0) + COALESCE(( SELECT pshi.od_send_cost + pshi.od_send_cost2 FROM pet_payment_sub_ship_info pshi WHERE pshi.payment_sub_info_id = ppi.payment_sub_info_id AND pshi.del_fl = 0 ORDER BY pshi.create_ymd DESC LIMIT 1 ), 0) AS it_total_price, CASE WHEN gsi.it_img1 != '' THEN CONCAT(#{imageServerUri}, gsi.it_img1) ELSE NULL END AS it_img1, ppi.create_ymd, -- 다음 결제 예정일 계산 CASE -- 조건: 결제 이력이 없고, 오늘 가입 → 시작일 = 예정일 WHEN ppi.payment_last_day IS NULL THEN ppi.payment_start_day
-- WEEKLY 정기결제 WHEN ppsc.code_type = 'WEEKLY' THEN DATE_ADD( COALESCE(ppi.payment_last_day, ppi.payment_start_day), INTERVAL ppsc.code_value DAY )
-- MONTHLY 정기결제 WHEN ppsc.code_type = 'MONTHLY' THEN CASE WHEN DAY(ppi.payment_start_day) >= 29 THEN LAST_DAY( DATE_ADD( COALESCE(ppi.payment_last_day, ppi.payment_start_day), INTERVAL ppsc.code_value MONTH ) ) ELSE DATE_ADD( COALESCE(ppi.payment_last_day, ppi.payment_start_day), INTERVAL ppsc.code_value MONTH ) END ELSE NULL END AS next_payment_due_date, COALESCE(( SELECT JSON_ARRAYAGG( JSON_OBJECT( 'itId', ppsci.it_id, 'ctOption', ppsci.ct_option, 'ctQty', ppsci.ct_qty, 'ioType', ppsci.io_type, 'ctPrice', CASE WHEN ppsci.io_type = 0 THEN ((ppsci.ct_price)) WHEN ppsci.io_type = 1 THEN (sio.io_price) ELSE 0 END, 'ctTotalPrice', CASE WHEN ppsci.io_type = 0 THEN ((ppsci.ct_price) * ppsci.ct_qty) WHEN ppsci.io_type = 1 THEN (sio.io_price * ppsci.ct_qty) ELSE 0 END ) ) FROM pet_payment_sub_cart_info ppsci JOIN g5_shop_item_option sio ON ppsci.io_id = sio.io_id AND ppsci.it_id = sio.it_id WHERE ppsci.payment_sub_info_id = ppi.payment_sub_info_id AND ppsci.del_fl = 0 ), JSON_ARRAY()) AS cart_list, COALESCE(( SELECT ppsci.pet_id FROM pet_payment_sub_cart_info ppsci WHERE ppsci.payment_sub_info_id = ppi.payment_sub_info_id AND ppsci.del_fl = 0 LIMIT 1 ), 0) AS pet_id FROM pet_payment_sub_info ppi INNER JOIN g5_shop_item gsi ON gsi.it_id = ppi.it_id INNER JOIN pet_payment_ship_code ppsc ON ppi.payment_period_cd_id = ppsc.payment_ship_code_id WHERE ppi.mb_id = #{mbId} AND ppi.del_fl = 0 ORDER BY ppi.create_ymd DESC LIMIT #{pageNo}, #{pageSize};

SELECT ppi.payment_sub_info_id, ppi.mb_id, ppi.payment_period_cd_id, ppi.payment_start_day, ppi.it_id, gsi.it_name, COALESCE(( SELECT SUM( CASE WHEN ppsci.io_type = 0 THEN ((ppsci.ct_price) * ppsci.ct_qty) WHEN ppsci.io_type = 1 THEN (sio.io_price * ppsci.ct_qty) ELSE 0 END ) FROM pet_payment_sub_cart_info ppsci JOIN g5_shop_item_option sio ON ppsci.io_id = sio.io_id AND ppsci.it_id = sio.it_id WHERE ppsci.payment_sub_info_id = ppi.payment_sub_info_id AND ppsci.del_fl = 0 ), 0) + COALESCE(( SELECT pshi.od_send_cost + pshi.od_send_cost2 FROM pet_payment_sub_ship_info pshi WHERE pshi.payment_sub_info_id = ppi.payment_sub_info_id AND pshi.del_fl = 0 ORDER BY pshi.create_ymd DESC LIMIT 1 ), 0) AS it_total_price, CASE WHEN gsi.it_img1 != '' THEN CONCAT(#{imageServerUri}, gsi.it_img1) ELSE NULL END AS it_img1, psii.card_name, psii.card_number, ppi.create_ymd, -- 다음 결제 예정일 계산 CASE -- 조건: 결제 이력이 없고, 오늘 가입 → 시작일 = 예정일 WHEN ppi.payment_last_day IS NULL THEN ppi.payment_start_day
-- WEEKLY 정기결제 WHEN ppsc.code_type = 'WEEKLY' THEN DATE_ADD( COALESCE(ppi.payment_last_day, ppi.payment_start_day), INTERVAL ppsc.code_value DAY )
-- MONTHLY 정기결제 WHEN ppsc.code_type = 'MONTHLY' THEN CASE WHEN DAY(ppi.payment_start_day) >= 29 THEN LAST_DAY( DATE_ADD( COALESCE(ppi.payment_last_day, ppi.payment_start_day), INTERVAL ppsc.code_value MONTH ) ) ELSE DATE_ADD( COALESCE(ppi.payment_last_day, ppi.payment_start_day), INTERVAL ppsc.code_value MONTH ) END ELSE NULL END AS next_payment_due_date, COALESCE(( SELECT JSON_ARRAYAGG( JSON_OBJECT( 'itId', ppsci.it_id, 'ctOption', ppsci.ct_option, 'ctQty', ppsci.ct_qty, 'ioType', ppsci.io_type, 'ctPrice', CASE WHEN ppsci.io_type = 0 THEN ((ppsci.ct_price)) WHEN ppsci.io_type = 1 THEN (sio.io_price) ELSE 0 END, 'ctTotalPrice', CASE WHEN ppsci.io_type = 0 THEN ((ppsci.ct_price) * ppsci.ct_qty) WHEN ppsci.io_type = 1 THEN (sio.io_price * ppsci.ct_qty) ELSE 0 END ) ) FROM pet_payment_sub_cart_info ppsci JOIN g5_shop_item_option sio ON ppsci.io_id = sio.io_id AND ppsci.it_id = sio.it_id WHERE ppsci.payment_sub_info_id = ppi.payment_sub_info_id AND ppsci.del_fl = 0 ), JSON_ARRAY()) AS cart_list, COALESCE(( SELECT ppsci.pet_id FROM pet_payment_sub_cart_info ppsci WHERE ppsci.payment_sub_info_id = ppi.payment_sub_info_id AND ppsci.del_fl = 0 LIMIT 1 ), 0) AS pet_id FROM pet_payment_sub_info ppi INNER JOIN g5_shop_item gsi ON gsi.it_id = ppi.it_id INNER JOIN ( SELECT psi.payment_sub_info_id, psi.card_name, psi.card_number FROM pet_payment_sub_info_history psi WHERE psi.status = 1 AND psi.del_fl = 0 AND psi.payment_sub_info_id = #{paymentSubInfoId} ORDER BY psi.create_ymd DESC LIMIT 1 ) psii ON psii.payment_sub_info_id = ppi.payment_sub_info_id INNER JOIN pet_payment_ship_code ppsc ON ppi.payment_period_cd_id = ppsc.payment_ship_code_id WHERE ppi.payment_sub_info_id = #{paymentSubInfoId} AND ppi.del_fl = 0;

SELECT
it_name, it_price, it_10
FROM g5_shop_item WHERE it_id = #{itId}

